/// at startup; `package-moved` changes map an installed package to another
/// directory without removing it first, or change or locally override a package
/// the DSH installation provides; `host-module` changes reach modules the
/// running process itself imports; `unmanaged-plugin` changes reach a plugin
/// running outside a Loader entry; `module-comparison` means loaded modules
/// could not be compared with disk.
final class RestartReason {
  const RestartReason._(this.value);

  /// Wraps a value this generation does not know; kept verbatim.
  const RestartReason.unrecognized(this.value);
  static const hostModule = RestartReason._('host-module');
  static const moduleComparison = RestartReason._('module-comparison');
  static const noHmr = RestartReason._('no-hmr');
  static const packageMoved = RestartReason._('package-moved');
  static const unmanagedPlugin = RestartReason._('unmanaged-plugin');
  static const List<RestartReason> values = [
    hostModule,
    moduleComparison,
    noHmr,
    packageMoved,
    unmanagedPlugin,
  ];
  final String value;
  bool get isKnown => values.any((v) => v.value == value);
  factory RestartReason.fromJson(Object? json, [String path = r'$']) {
    final s = _str(json, path);
    for (final v in values) {
      if (v.value == s) return v;
    }
    return RestartReason.unrecognized(s);
  }
  String toJson() => value;
  @override
  bool operator ==(Object other) =>
      other is RestartReason && other.value == value;
  @override
  int get hashCode => value.hashCode;
  @override
  String toString() => 'RestartReason($value)';
}
